<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>My Bookmarks</title>
<link rel="stylesheet" href="styles.css" />
</head>
<body>
<header>
  <h1>My Bookmarks</h1>
  <div id="userbar" class="userbar" hidden>
    <span id="whoami" class="whoami"></span>
    <button id="signout" class="btn-light small">Sign out</button>
  </div>
</header>

<!-- Sign-in / register (SCN-013) -->
<div class="signin" id="signin" hidden>
  <div class="card auth">
    <h2 id="authTitle">Sign in to your bookmarks</h2>
    <p class="muted" id="authIntro">Your collection is kept in one place so you can reach it from any device.</p>
    <label for="email">Email</label>
    <input id="email" type="email" autocomplete="username" placeholder="you@example.com" />
    <label for="password">Password</label>
    <input id="password" type="password" autocomplete="current-password" placeholder="••••••••" />
    <div id="authError" class="msg warn" role="alert"></div>
    <button id="authSubmit" class="btn-primary block">Sign in</button>
    <p class="switch muted">
      <span id="switchPrompt">New here?</span>
      <a href="#" id="switchLink">Create an account</a>
    </p>
  </div>
</div>

<!-- Main app -->
<main id="app" hidden>
  <section class="card">
    <div class="searchwrap">
      <input id="search" type="search" placeholder="Search your bookmarks…" autocomplete="off" />
    </div>
    <div class="searchmeta" id="searchmeta" aria-live="polite"></div>
  </section>

  <section class="card">
    <details class="saver" id="saver">
      <summary>Save a link</summary>
      <label for="url">Paste a link</label>
      <input id="url" type="url" placeholder="https://…" autocomplete="off" />
      <div id="saveStatus" class="msg"></div>
      <label for="title">Title</label>
      <input id="title" type="text" placeholder="Filled in automatically" />
      <label for="desc">Description</label>
      <textarea id="desc" placeholder="Filled in automatically"></textarea>
      <label for="note">Personal note (optional)</label>
      <textarea id="note" placeholder="Your own note — why you saved it, what to look for…"></textarea>
      <label for="taginput">Tags</label>
      <div class="tagbox" id="tagbox"><input id="taginput" type="text" placeholder="Type a tag, press Enter" autocomplete="off" /></div>
      <div class="hint">Press Enter (or comma) to turn a word into a tag. Click a tag's × to remove it.</div>
      <div class="suggest" id="suggest"></div>
      <button id="save" class="btn-primary" disabled>Save bookmark</button>
    </details>
  </section>

  <section class="card">
    <div class="tabs" id="tabs">
      <button data-t="toread" class="active">To read <span class="badge" id="badge-toread">0</span></button>
      <button data-t="finished">Finished <span class="badge" id="badge-finished">0</span></button>
      <button data-t="archived">Archived <span class="badge" id="badge-archived">0</span></button>
    </div>
    <div id="empty" class="empty" hidden></div>
    <ul id="list" class="list"></ul>
  </section>
</main>

<!-- Confirm dialog (SCN-012) -->
<div class="overlay" id="overlay" hidden>
  <div class="modal">
    <h3 id="confirmTitle">Delete this bookmark?</h3>
    <p id="confirmBody" class="muted"></p>
    <div class="modal-row">
      <button id="confirmCancel" class="btn-light">Cancel</button>
      <button id="confirmOk" class="btn-danger">Delete permanently</button>
    </div>
  </div>
</div>

<script src="app.js"></script>
</body>
</html>

