:root {
  --bg:#f6f7f9; --card:#ffffff; --ink:#1f2933; --muted:#6b7280; --line:#e5e7eb;
  --accent:#2563eb; --accent-soft:#eff4ff;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--ink); }
header { padding:18px 28px; background:var(--card); border-bottom:1px solid var(--line); display:flex; align-items:center; justify-content:space-between; }
header h1 { margin:0; font-size:20px; }
.userbar { display:flex; align-items:center; gap:12px; }
.whoami { font-size:13px; color:var(--muted); }
main, .signin { max-width:760px; margin:0 auto; padding:24px 20px 60px; }
.signin { max-width:380px; margin-top:6vh; }
.card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:20px; margin-bottom:20px; }
.card.auth h2 { margin:0 0 6px; font-size:17px; }
.muted { color:var(--muted); font-size:13px; }
label { display:block; font-size:12px; color:var(--muted); margin:12px 0 5px; }
input[type=text],input[type=url],input[type=email],input[type=password],input[type=search],textarea {
  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; background:#fff;
}
textarea { resize:vertical; min-height:60px; }
button { border:none; border-radius:8px; padding:10px 16px; font-size:14px; font-weight:600; cursor:pointer; }
button.small { padding:6px 12px; font-size:12px; }
.btn-primary { background:var(--accent); color:#fff; }
.btn-primary:disabled { background:#9db8f0; cursor:default; }
.btn-primary.block, .block { width:100%; margin-top:14px; }
.btn-light { background:#fff; border:1px solid var(--line); color:var(--ink); }
.btn-danger { background:#dc2626; color:#fff; }
.hint { font-size:11px; color:var(--muted); margin-top:4px; }
.msg { font-size:12px; min-height:16px; margin-top:8px; }
.msg.warn { color:#b45309; }
.msg.info { color:#1e40af; }
.msg.ok { color:#15803d; }
.msg.fetching { color:var(--accent); }
.switch { margin:14px 0 0; text-align:center; }
.switch a { color:var(--accent); text-decoration:none; }

.autofilled { background:var(--accent-soft); border-color:#c7d8fb; transition:background .4s ease; }
#save { margin-top:16px; }

.searchwrap { position:relative; }
#search { padding-left:36px; font-size:15px; }
.searchwrap::before { content:"🔍"; position:absolute; left:12px; top:50%; transform:translateY(-50%); font-size:14px; opacity:.6; }
.searchmeta { font-size:12px; color:var(--muted); margin-top:8px; min-height:16px; }
.searchmeta b { color:var(--ink); }
.activefilter { display:inline-flex; align-items:center; gap:6px; background:var(--accent-soft); color:#1e40af; border:1px solid #c7d8fb; border-radius:999px; padding:2px 10px; margin-left:6px; }
.activefilter button { background:none; border:none; color:#1e40af; cursor:pointer; font-weight:700; padding:0; }

.saver summary { cursor:pointer; font-size:15px; font-weight:600; list-style:none; }
.saver summary::-webkit-details-marker { display:none; }
.saver summary::before { content:"＋ "; color:var(--accent); }

.tabs { display:flex; gap:4px; border-bottom:1px solid var(--line); margin-bottom:16px; flex-wrap:wrap; }
.tabs button { font-size:14px; font-weight:600; border:none; background:none; padding:10px 16px; cursor:pointer; color:var(--muted); border-bottom:2px solid transparent; margin-bottom:-1px; }
.tabs button.active { color:var(--accent); border-bottom-color:var(--accent); }
.tabs .badge { font-size:11px; background:#eef2f7; color:#334155; border-radius:999px; padding:1px 7px; margin-left:6px; }

.empty { text-align:center; color:var(--muted); padding:30px 10px; font-size:14px; }
ul.list { list-style:none; margin:0; padding:0; }
li.item { border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:12px; }
li.item.archived { background:#fafafa; opacity:.9; }
li.item.flash { animation:flash 1.8s ease; }
@keyframes flash { 0%{ background:#fef3c7; border-color:#fcd34d; } 100%{ background:#fff; border-color:var(--line); } }
.itemhead { display:flex; justify-content:space-between; align-items:flex-start; gap:10px; }
li.item .title { font-weight:600; font-size:15px; }
li.item .title a { color:var(--ink); text-decoration:none; word-break:break-word; }
li.item .url { font-size:12px; color:var(--muted); margin-top:2px; word-break:break-all; }
li.item .desc { font-size:13px; color:#4b5563; margin-top:8px; word-break:break-word; }
li.item .note { font-size:13px; color:#7c3f00; background:#fffbeb; border:1px solid #fde68a; border-radius:8px; padding:8px 10px; margin-top:8px; word-break:break-word; }
li.item .note::before { content:"📝 "; }
mark { background:#fde68a; color:inherit; border-radius:3px; padding:0 1px; }
.chips { margin-top:10px; }
.chip { display:inline-block; font-size:12px; color:#334155; background:#eef2f7; border:1px solid #e2e8f0; border-radius:999px; padding:3px 10px; margin:0 6px 6px 0; cursor:pointer; }
.chip:hover { background:var(--accent-soft); border-color:#c7d8fb; color:#1e40af; }
.actions { display:flex; gap:6px; flex:none; flex-wrap:wrap; justify-content:flex-end; }
.actbtn { font-size:12px; font-weight:600; border:1px solid var(--line); background:#fff; border-radius:999px; padding:5px 12px; cursor:pointer; white-space:nowrap; }
.actbtn.done { background:#ecfdf5; border-color:#a7f3d0; color:#047857; }
.actbtn.danger { border-color:#fecaca; color:#b91c1c; }

.editform { margin-top:12px; padding-top:12px; border-top:1px dashed var(--line); }
.editbtns { display:flex; gap:8px; margin-top:12px; }
.tagbox { display:flex; flex-wrap:wrap; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:7px 8px; background:#fff; }
.tagbox:focus-within { border-color:var(--accent); }
.tagbox .chip { display:inline-flex; align-items:center; margin:0; background:var(--accent-soft); border-color:#c7d8fb; color:#1e40af; cursor:default; }
.tagbox .chip button { background:none; border:none; color:#1e40af; font-size:14px; line-height:1; padding:0 0 0 6px; cursor:pointer; font-weight:700; }
.tagbox input { border:none; outline:none; flex:1; min-width:120px; padding:4px; font-size:14px; }
.suggest { margin-top:8px; }
.suggest > span { display:inline-block; font-size:12px; color:var(--muted); margin-right:6px; }
.suggest .sug { color:var(--accent); background:var(--accent-soft); border:1px solid #c7d8fb; border-radius:999px; padding:3px 10px; margin:0 6px 6px 0; cursor:pointer; font-size:12px; }

.overlay { position:fixed; inset:0; background:rgba(31,41,51,.45); display:flex; align-items:center; justify-content:center; z-index:50; }
.modal { background:#fff; border-radius:12px; padding:22px; max-width:380px; width:90%; box-shadow:0 12px 40px rgba(0,0,0,.2); }
.modal h3 { margin:0 0 8px; font-size:16px; }
.modal p { margin:0 0 16px; font-size:13px; }
.modal-row { display:flex; gap:8px; justify-content:flex-end; }

